<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Expense Tracker</title>
<style>
  :root{
    --bg:#f5f6f8;
    --card:#ffffff;
    --ink:#1e2430;
    --muted:#606a7b;
    --line:#dde1e8;
    --accent:#2f6fed;
    --danger:#c0392b;
  }
  *{box-sizing:border-box}
  body{
    margin:0;
    padding:20px;
    background:var(--bg);
    color:var(--ink);
    font:15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  }
  h1{font-size:22px;margin:0 0 16px}
  h2{font-size:15px;margin:0 0 10px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
  .wrap{max-width:920px;margin:0 auto;display:grid;gap:16px}
  .card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px}
  .grid{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));align-items:end}
  label{display:block;font-size:12px;color:var(--muted);margin-bottom:4px;font-weight:600}
  input,select,button{font:inherit;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);width:100%}
  button{cursor:pointer}
  #add-expense{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}
  #add-expense:hover{filter:brightness(1.07)}
  #form-error{margin-top:10px;color:var(--danger);font-weight:600;min-height:1.2em}
  #form-error:empty{min-height:1.2em}
  table{width:100%;border-collapse:collapse}
  th,td{text-align:left;padding:8px 6px;border-bottom:1px solid var(--line);vertical-align:middle}
  th{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted)}
  td.amt,th.amt{text-align:right;font-variant-numeric:tabular-nums}
  .exp-del{width:auto;padding:4px 10px;border-color:#e7b6b0;color:var(--danger);background:#fff6f5}
  .exp-del:hover{background:#ffe9e6}
  .totals{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
  .cat-total{background:#eef2fb;border:1px solid #dbe4f8;border-radius:20px;padding:4px 12px;font-size:13px}
  #total-line{font-size:18px;font-weight:700;margin:0 0 12px}
  #total{font-variant-numeric:tabular-nums}
  .empty{color:var(--muted);padding:10px 6px}
  .row-actions{width:1%;white-space:nowrap}
  .note{color:var(--muted)}
</style>
</head>
<body>
<div class="wrap">
  <h1>Personal Expense Tracker</h1>

  <section class="card">
    <h2>Add expense</h2>
    <form id="expense-form" novalidate>
      <div class="grid">
        <div>
          <label for="amount">Amount</label>
          <input type="number" id="amount" name="amount" step="0.01" placeholder="0.00" inputmode="decimal">
        </div>
        <div>
          <label for="category">Category</label>
          <select id="category" name="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div>
          <label for="date">Date</label>
          <input type="date" id="date" name="date">
        </div>
        <div>
          <label for="note">Note (optional)</label>
          <input type="text" id="note" name="note" placeholder="e.g. weekly shop">
        </div>
        <div>
          <button type="submit" id="add-expense">Add expense</button>
        </div>
      </div>
      <div id="form-error" role="alert" aria-live="polite"></div>
    </form>
  </section>

  <section class="card">
    <h2>Filters</h2>
    <div class="grid">
      <div>
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div>
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div>
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
      <div>
        <button type="button" id="clear-filters">Clear filters</button>
      </div>
    </div>
  </section>

  <section class="card">
    <h2>Summary</h2>
    <p id="total-line">Total: <span id="total">0.00</span></p>
    <div class="totals" id="cat-totals">
      <span class="cat-total" data-cat="groceries">groceries: 0.00</span>
      <span class="cat-total" data-cat="transport">transport: 0.00</span>
      <span class="cat-total" data-cat="bills">bills: 0.00</span>
      <span class="cat-total" data-cat="fun">fun: 0.00</span>
    </div>
  </section>

  <section class="card">
    <h2>Expenses</h2>
    <table>
      <thead>
        <tr>
          <th class="amt">Amount</th>
          <th>Category</th>
          <th>Date</th>
          <th>Note</th>
          <th class="row-actions"></th>
        </tr>
      </thead>
      <tbody id="expense-list"></tbody>
    </table>
    <div class="empty" id="empty-msg" hidden>No expenses to show.</div>
  </section>
</div>

<script>
(function () {
  "use strict";

  var STORE_KEY = "expense-tracker-v1";
  var CATEGORIES = ["groceries", "transport", "bills", "fun"];

  var form = document.getElementById("expense-form");
  var amountEl = document.getElementById("amount");
  var categoryEl = document.getElementById("category");
  var dateEl = document.getElementById("date");
  var noteEl = document.getElementById("note");
  var errEl = document.getElementById("form-error");

  var listEl = document.getElementById("expense-list");
  var emptyMsg = document.getElementById("empty-msg");
  var totalEl = document.getElementById("total");

  var fCat = document.getElementById("filter-category");
  var fFrom = document.getElementById("filter-from");
  var fTo = document.getElementById("filter-to");
  var clearBtn = document.getElementById("clear-filters");

  var expenses = load();

  function load() {
    try {
      var raw = localStorage.getItem(STORE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data.filter(function (e) {
        return e && isFinite(Number(e.amount)) && typeof e.date === "string";
      }).map(function (e, i) {
        return {
          id: e.id != null ? String(e.id) : "id" + i + "_" + Date.now(),
          amount: Number(e.amount),
          category: CATEGORIES.indexOf(e.category) >= 0 ? e.category : "groceries",
          date: e.date,
          note: typeof e.note === "string" ? e.note : "",
          created: Number(e.created) || i
        };
      });
    } catch (err) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(expenses));
    } catch (err) { /* storage unavailable; keep working in-memory */ }
  }

  function fmt(n) {
    return (Math.round(n * 100) / 100).toFixed(2);
  }

  function sortExpenses() {
    // newest first: by date desc, then by insertion time desc
    expenses.sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return b.created - a.created;
    });
  }

  function visible(exp) {
    var cat = fCat.value;
    if (cat && cat !== "all" && exp.category !== cat) return false;
    var from = fFrom.value;
    var to = fTo.value;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  function render() {
    sortExpenses();
    listEl.textContent = "";

    var total = 0;
    var catTotals = {};
    CATEGORIES.forEach(function (c) { catTotals[c] = 0; });

    var shown = 0;

    expenses.forEach(function (exp) {
      var tr = document.createElement("tr");
      tr.className = "expense";
      tr.setAttribute("data-id", exp.id);
      tr.setAttribute("data-category", exp.category);
      tr.setAttribute("data-date", exp.date);
      tr.setAttribute("data-amount", fmt(exp.amount));

      var tdA = document.createElement("td");
      tdA.className = "amt exp-amount";
      tdA.textContent = fmt(exp.amount);
      tr.appendChild(tdA);

      var tdC = document.createElement("td");
      tdC.className = "exp-category";
      tdC.textContent = exp.category;
      tr.appendChild(tdC);

      var tdD = document.createElement("td");
      tdD.className = "exp-date";
      tdD.textContent = exp.date;
      tr.appendChild(tdD);

      var tdN = document.createElement("td");
      tdN.className = "exp-note note";
      tdN.textContent = exp.note || "";
      tr.appendChild(tdN);

      var tdX = document.createElement("td");
      tdX.className = "row-actions";
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "exp-del";
      btn.textContent = "Delete";
      btn.setAttribute("aria-label", "Delete expense");
      btn.setAttribute("data-id", exp.id);
      tdX.appendChild(btn);
      tr.appendChild(tdX);

      var isVisible = visible(exp);
      if (!isVisible) {
        tr.style.display = "none";
        tr.hidden = true;
        tr.setAttribute("aria-hidden", "true");
      } else {
        tr.style.display = "";
        shown++;
        total += exp.amount;
        if (catTotals.hasOwnProperty(exp.category)) {
          catTotals[exp.category] += exp.amount;
        } else {
          catTotals[exp.category] = exp.amount;
        }
      }

      listEl.appendChild(tr);
    });

    totalEl.textContent = fmt(total);

    CATEGORIES.forEach(function (c) {
      var el = document.querySelector('.cat-total[data-cat="' + c + '"]');
      if (el) el.textContent = c + ": " + fmt(catTotals[c] || 0);
    });

    emptyMsg.hidden = shown !== 0;
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();

    var rawAmount = String(amountEl.value).trim();
    var date = String(dateEl.value).trim();

    if (rawAmount === "") {
      errEl.textContent = "Please enter an amount.";
      return;
    }
    var amount = Number(rawAmount);
    if (!isFinite(amount) || isNaN(amount)) {
      errEl.textContent = "Amount must be a number.";
      return;
    }
    if (amount <= 0) {
      errEl.textContent = "Amount must be greater than zero.";
      return;
    }
    if (!date) {
      errEl.textContent = "Please choose a date.";
      return;
    }

    var category = categoryEl.value || "groceries";

    expenses.push({
      id: "e" + Date.now() + "_" + Math.random().toString(36).slice(2, 8),
      amount: amount,
      category: category,
      date: date,
      note: String(noteEl.value || "").trim(),
      created: Date.now()
    });

    save();
    errEl.textContent = "";
    amountEl.value = "";
    noteEl.value = "";
    render();
    amountEl.focus();
  });

  listEl.addEventListener("click", function (e) {
    var btn = e.target.closest ? e.target.closest(".exp-del") : null;
    if (!btn) return;
    var id = btn.getAttribute("data-id");
    expenses = expenses.filter(function (x) { return x.id !== id; });
    save();
    render();
  });

  [fCat, fFrom, fTo].forEach(function (el) {
    el.addEventListener("change", render);
    el.addEventListener("input", render);
  });

  clearBtn.addEventListener("click", function () {
    fCat.value = "all";
    fFrom.value = "";
    fTo.value = "";
    render();
  });

  // default date to today for convenience
  (function () {
    var d = new Date();
    var iso = d.getFullYear() + "-" +
      String(d.getMonth() + 1).padStart(2, "0") + "-" +
      String(d.getDate()).padStart(2, "0");
    if (!dateEl.value) dateEl.value = iso;
  })();

  render();
})();
</script>
</body>
</html>
